export const BanToggleButton = ({
    room,
    member,
    startUpdating,
    stopUpdating,
}: Omit<IBaseRoomProps, "powerLevels">): JSX.Element => {
    const cli = useContext(MatrixClientContext);
    const pendingActions = useContext(PendingAdminActionContext);
    const disabled = pendingActions.pendingUserId === member.userId;

    const isBanned = member.membership === "ban";
    const onBanOrUnban = async (): Promise<void> => {
        if (!pendingActions.begin(member.userId)) return;
        startUpdating();
        try {
        const commonProps = {
            member,
            action: room.isSpaceRoom()
                ? isBanned
                    ? _t("Unban from space")
                    : _t("Ban from space")
                : isBanned
                ? _t("Unban from room")
                : _t("Ban from room"),
            title: isBanned
                ? _t("Unban from %(roomName)s", { roomName: room.name })
                : _t("Ban from %(roomName)s", { roomName: room.name }),
            askReason: !isBanned,
            danger: !isBanned,
        };

        let finished: Promise<[success?: boolean, reason?: string, rooms?: Room[]]>;

        if (room.isSpaceRoom()) {
            ({ finished } = Modal.createDialog(
                ConfirmSpaceUserActionDialog,
                {
                    ...commonProps,
                    space: room,
                    spaceChildFilter: isBanned
                        ? (child: Room) => {
                              // Return true if the target member is banned and we have sufficient PL to unban
                              const myMember = child.getMember(cli.credentials.userId || "");
                              const theirMember = child.getMember(member.userId);
            }
        }

        const powerLevelEvent = room.currentState.getStateEvents("m.room.power_levels", "");
        if (!powerLevelEvent) return;

        const powerLevels = powerLevelEvent.getContent();
        const levelToSend =
            (powerLevels.events ? powerLevels.events["m.room.message"] : null) || powerLevels.events_default;
        let level;
        if (muted) {
            // unmute
            level = levelToSend;
        } else {
            // mute
            level = levelToSend - 1;
        }
        level = parseInt(level);

        if (!isNaN(level)) {
            cli.setPowerLevel(roomId, target, level, powerLevelEvent)
                .then(
                    () => {
                        // NO-OP; rely on the m.room.member event coming down else we could
                        // get out of sync if we force setState here!
                        logger.log("Mute toggle success");
                    },
                    function (err) {
                        logger.error("Mute error: " + err);
                        Modal.createDialog(ErrorDialog, {
                            title: _t("Error"),
                            description: _t("Failed to mute user"),
                        });
                    },
                )
                .finally(() => stopUpdating());
        }
        } finally {
            pendingActions.end(member.userId);
            stopUpdating();
        }
    };

    const classes = classNames("mx_UserInfo_field", {
        mx_UserInfo_destructive: !muted,
    });

    const muteLabel = muted ? _t("Unmute") : _t("Mute");
    return (
        <AccessibleButton disabled={disabled} kind="link" className={classes} onClick={onMuteToggle}>
            {muteLabel}
        </AccessibleButton>
    );
};

